from collections import deque,Counter

def comps(g, color, diagonal=False):
    H=len(g); W=len(g[0]); vis=set(); out=[]; steps=[(-1,0),(1,0),(0,-1),(0,1)]
    if diagonal: steps += [(-1,-1),(-1,1),(1,-1),(1,1)]
    for r in range(H):
      for c in range(W):
       if g[r][c]!=color or (r,c) in vis: continue
       q=[(r,c)]; vis.add((r,c)); obj=[]
       while q:
        x,y=q.pop(); obj.append((x,y))
        for dx,dy in steps:
         p=(x+dx,y+dy)
         if 0<=p[0]<H and 0<=p[1]<W and p not in vis and g[p[0]][p[1]]==color:
          vis.add(p);q.append(p)
       out.append(obj)
    return sorted(out,key=len,reverse=True)
